test("validateVisualEvidenceStats rejects blank or low-contrast screenshots", () => {
  assert.equal(
    validateVisualEvidenceStats({
      width: 3024,
      height: 1964,
      sampleCount: 4096,
      nonDarkRatio: 0.02,
      lumaSpread: 32,
    }),
    null,
  );
  assert.match(
    validateVisualEvidenceStats({
      width: 3024,
      height: 1964,
      sampleCount: 4096,
      nonDarkRatio: 0,
      lumaSpread: 0,
    }),
    /blank or black/,
  );
  assert.match(
    validateVisualEvidenceStats({
      width: 3024,
      height: 1964,
      sampleCount: 4096,
      nonDarkRatio: 0.02,
      lumaSpread: 2,
    }),
    /too little visible contrast/,
  );
});

